package android.view; public class KeyEvent { public static final int ACTION_DOWN=0,ACTION_UP=1,FLAG_SOFT_KEYBOARD=2; final int code,action,device,scan,flags,meta,repeat; final long time; public KeyEvent(int c,int a,int d,int s,int f,long t){this(c,a,d,s,f,t,0,0);} public KeyEvent(int c,int a,int d,int s,int f,long t,int m,int r){code=c;action=a;device=d;scan=s;flags=f;time=t;meta=m;repeat=r;} public int getKeyCode(){return code;} public int getAction(){return action;} public int getDeviceId(){return device;} public InputDevice getDevice(){return InputDevice.getDevice(device);} public int getScanCode(){return scan;} public int getFlags(){return flags;} public int getMetaState(){return meta;} public int getRepeatCount(){return repeat;} public long getDownTime(){return time;} public boolean isFromSource(int s){return s==InputDevice.SOURCE_KEYBOARD;} }
